    \draw (A) arc[start angle=180, end angle=0, radius=5]
    node[midway,above] {};

ode[above=0.5cm] at (1,3) {$S_3$};

    \coordinate (C) at (8.3,0);
     ill (C) circle (2pt) node[below] {$C$};

\end{tikzpicture}

